AND t1.typeName LIKE CONCAT('%',#{query.typeName},'%')
AND t1.code LIKE CONCAT('%',#{query.code},'%')
AND t1.level = #{query.level}
AND t2.staff_code = #{staffCode}
AND t1.state IN
#{state}
